def table_head(columns: str) -> list[str]:
    """`"A|B|C"` → a markdown header row and its rule. Column names are pack text."""
    cells = [c.strip() for c in columns.split("|")]
    return ["| " + " | ".join(cells) + " |", "| " + " | ".join("---" for _ in cells) + " |"]
